-- Import unique du fichier edition/coordonee dans la base mondeLV (genre 'edition').
-- A executer une seule fois dans phpMyAdmin, apres mondeLV.sql.
-- Relancer ce script remplace les objets 'edition' existants.
USE mondeLV;
SET NAMES utf8mb4;

DELETE FROM monde_objet WHERE genre = 'edition';
SET @rev = (SELECT revision FROM monde_compteur WHERE id = 1) + 1;


UPDATE monde_compteur SET revision = @rev WHERE id = 1;
